console.info("[SOCIETY] cookFirstDish.js loaded");

// First-dish bonus for the cook profession. The first time a cook prepares each
// dish of COOK_FIRST_DISH_IDS (cookFirstDishList.js, generated by
// sunlit_tools/cook_first_dishes.py: finished dishes, no intermediates, storage
// blocks or alcoholic drinks), they earn its base sell value in coins and
// Culinaria XP. Once per dish per player, kept in persistentData (COOK_FD_DONE_KEY).
// A dish counts as prepared when:
//   - the vanilla "crafted" stat of the dish goes up (result slots of the crafting
//     table, Farmer's Delight pot, kettle, Youkai pots, stoves and furnaces, plus
//     Hands-On Delight's board assembly, pot and serving, which call onCraftedBy). Shop
//     result slots raise that stat too, so ticks with a shop or merchant menu open
//     only move the baseline;
//   - right after a right-click on an in-world cooking station (COOK_FD_STATIONS)
//     the dish count in the inventory went up. Dishes the player put into a
//     station (count went down on a click) are remembered and never pay when
//     taken back.
// Dishes crafted before this file existed are marked done on the first login.

const COOK_FD_DONE_KEY = "sunlitCookFirstDishes";
const COOK_FD_DEPOSIT_KEY = "sunlitCookDeposited";
const COOK_FD_POLL_TICKS = 10;
const COOK_FD_XP_BASE = 15;
const COOK_FD_XP_DIVISOR = 10;
const COOK_FD_XP_MAX = 120;
const COOK_FD_SHOP_MENU = /Shop|Merchant|Trader|Vendor/;
const COOK_FD_STATIONS = [
  /^farmersdelight:(cooking_pot|cutting_board|skillet|stove)$/,
  /^kaleidoscope_cookery:(pot|stockpot|steamer|teapot)$/,
  /^farm_and_charm:(cooking_pot|roaster|crafting_bowl|stove)$/,
  /^bakery:(baker_station|small_cooking_pot)$/,
  /^candlelight:(cooking_pan|cooking_pot)$/,
  /^meadow:cooking_cauldron$/,
  /^cuisinedelight:cuisine_skillet$/,
  /^youkaishomecoming:(cooking_short_iron_pot|cooking_small_iron_pot|cooking_stockpot|steamer_pot|steamer_rack|cuisine_board)$/,
  /^herbalbrews:(tea_kettle|copper_tea_kettle)$/,
  /^refurbished_furniture:(.+_cutting_board|.+_grill|frying_pan|.+_toaster)$/,
];
const $CookFdBlockItem = Java.loadClass("net.minecraft.world.item.BlockItem");

// Built on first use: id -> { item, value }. Only items that exist, have a sell
// value and are food (edible, a drink, or a placeable feast/pie block).
let cookFdDishes = null;
const cookFdDishMap = () => {
  if (cookFdDishes) return cookFdDishes;
  let map = {};
  COOK_FIRST_DISH_IDS.forEach((id) => {
    try {
      let stack = Item.of(id);
      if (stack.isEmpty()) return;
      let trade = global.trades.get(id);
      let value = trade ? Math.round(Number(trade.value)) : 0;
      if (!(value > 0)) return;
      let item = stack.getItem();
      let food =
        stack.isEdible() ||
        String(stack.getUseAnimation()) === "DRINK" ||
        item instanceof $CookFdBlockItem;
      if (food) map[id] = { item: item, value: value };
    } catch (err) {
      console.error(`[cook first dish] skipped ${id}: ${err}`);
    }
  });
  cookFdDishes = map;
  console.info(`[cook first dish] ${Object.keys(map).length} dishes`);
  return map;
};

const cookFdState = {};

const cookFdXp = (value) =>
  Math.min(COOK_FD_XP_MAX, COOK_FD_XP_BASE + Math.round(value / COOK_FD_XP_DIVISOR));

const cookFdIsCook = (player) => global.hasProfession(player, "cook");

const cookFdReward = (player, id) => {
  let dish = cookFdDishMap()[id];
  let done = player.persistentData.getCompound(COOK_FD_DONE_KEY);
  if (!dish || done.contains(id)) return;
  done.putBoolean(id, true);
  player.persistentData.put(COOK_FD_DONE_KEY, done);

  let xp = cookFdXp(dish.value);
  global.giveExperience(player.server, player, "culinaria", xp, false);
  global.calculateCoinsFromValue(dish.value, []).forEach((coin) => {
    if (coin.count > 0) player.give(Item.of(coin.id, coin.count));
  });
  let gainedXp = global.professionBoostedXp(player, "culinaria", xp);
  player.tell(
    Text.translatable("society.cook.first_dish", Item.of(id).getHoverName(), `${dish.value}`, `${gainedXp}`).gold()
  );
  player.server.runCommandSilent(
    `playsound tanukidecor:block.cash_register.ring player ${player.username} ${player.x} ${player.y} ${player.z} 0.6 1.2`
  );
};

// Snapshot of the crafted stat of every dish not done yet.
const cookFdCraftedSnapshot = (player, map, done) => {
  let counts = {};
  Object.keys(map).forEach((id) => {
    if (!done.contains(id)) counts[id] = player.stats.getItemsCrafted(map[id].item);
  });
  return counts;
};

// Marks as done every dish crafted before this feature, once per player.
const cookFdBaseline = (player) => {
  if (player.persistentData.contains(COOK_FD_DONE_KEY)) return;
  let map = cookFdDishMap();
  let done = player.persistentData.getCompound(COOK_FD_DONE_KEY);
  Object.keys(map).forEach((id) => {
    if (player.stats.getItemsCrafted(map[id].item) > 0) done.putBoolean(id, true);
  });
  player.persistentData.put(COOK_FD_DONE_KEY, done);
};

PlayerEvents.loggedIn((e) => {
  let player = e.player;
  if (!player || player.isFake()) return;
  try {
    delete cookFdState[String(player.getUuid())];
    cookFdBaseline(player);
  } catch (err) {
    console.error(`[cook first dish] baseline failed: ${err}`);
  }
});

PlayerEvents.tick((e) => {
  let player = e.player;
  if (!player || player.level.isClientSide() || player.isFake()) return;
  let uuid = String(player.getUuid());
  let state = cookFdState[uuid];
  if (!state) state = cookFdState[uuid] = { counts: null, shop: false };
  try {
    let menu = player.containerMenu;
    if (menu && COOK_FD_SHOP_MENU.test(String(menu.getClass().getSimpleName()))) state.shop = true;
    if (player.age % COOK_FD_POLL_TICKS != 0) return;
    // Only cooks are polled; the baseline restarts when the player becomes one.
    cookFdBaseline(player);
    if (!cookFdIsCook(player)) {
      state.counts = null;
      state.shop = false;
      return;
    }

    let map = cookFdDishMap();
    let done = player.persistentData.getCompound(COOK_FD_DONE_KEY);
    let current = cookFdCraftedSnapshot(player, map, done);
    let last = state.counts;
    let pay = last && !state.shop;
    state.counts = current;
    state.shop = false;
    if (!pay) return;
    Object.keys(current).forEach((id) => {
      if (current[id] > (last[id] || 0)) cookFdReward(player, id);
    });
  } catch (err) {
    console.error(`[cook first dish] crafted check failed: ${err}`);
  }
});

const cookFdInventoryCounts = (player, map) => {
  let counts = {};
  let inventory = player.getInventory();
  for (let i = 0; i < inventory.getContainerSize(); i++) {
    let stack = inventory.getItem(i);
    if (stack.isEmpty()) continue;
    let id = String(stack.getId());
    if (map[id]) counts[id] = (counts[id] || 0) + stack.getCount();
  }
  return counts;
};

BlockEvents.rightClicked((e) => {
  let { player, block, hand } = e;
  if (hand == "OFF_HAND" || !player || player.isFake() || player.level.isClientSide()) return;
  let blockId = String(block.id);
  if (!COOK_FD_STATIONS.some((pattern) => pattern.test(blockId))) return;
  if (!cookFdIsCook(player)) return;
  try {
    cookFdBaseline(player);
    let map = cookFdDishMap();
    let before = cookFdInventoryCounts(player, map);
    player.server.scheduleInTicks(1, () => {
      try {
        let after = cookFdInventoryCounts(player, map);
        let done = player.persistentData.getCompound(COOK_FD_DONE_KEY);
        let deposited = player.persistentData.getCompound(COOK_FD_DEPOSIT_KEY);
        let changed = false;
        Object.keys(before).forEach((id) => {
          if ((after[id] || 0) < before[id] && !done.contains(id) && !deposited.contains(id)) {
            deposited.putBoolean(id, true);
            changed = true;
          }
        });
        if (changed) player.persistentData.put(COOK_FD_DEPOSIT_KEY, deposited);
        Object.keys(after).forEach((id) => {
          if (after[id] > (before[id] || 0) && !deposited.contains(id)) cookFdReward(player, id);
        });
      } catch (err) {
        console.error(`[cook first dish] station check failed: ${err}`);
      }
    });
  } catch (err) {
    console.error(`[cook first dish] station click failed: ${err}`);
  }
});
